import { useState } from 'react';
import { Text, View } from 'react-native';
import { WebView } from 'react-native-webview';
import { useTheme } from '@/hooks/use-theme';
import { Spacing } from '@/constants/theme';

/** Displays trusted, bundled map HTML in the native app without opening a browser. */
/**
 * @param props.html - Complete HTML generated by createCampusMapHtml.
 * @returns The native map viewer, or an error message if loading fails.
 */
export default function CampusMapView({ html }: { html: string }) {
  const theme = useTheme();
  const [failed, setFailed] = useState(false);

  // Show a readable message if the WebView reports a failure.
  // Leaving and reopening the screen creates a fresh viewer.
  if (failed) {
    return <View accessibilityRole="alert" style={{ padding: Spacing.three }}><Text style={{ color: theme.text }}>Unable to display the map. Go back and reopen it to try again.</Text></View>;
  }

  // The HTML handles map dragging and zooming, so WebView scrolling is disabled.
  // JavaScript is needed for the controls and pointer event handlers.
  return (
    <WebView
      style={{ flex: 1 }}
      source={{ html }}
      // Inline HTML needs this whitelist; navigation is restricted below.
      originWhitelist={['*']}
      onShouldStartLoadWithRequest={({ url }: { url: string }) => url === 'about:blank'}
      onError={() => setFailed(true)}
      onContentProcessDidTerminate={() => setFailed(true)}
      scrollEnabled={false}
      javaScriptEnabled
    />
  );
}